@Model
class TaskItem {
    var title: String
    init(_ title: String) { self.title = title }
}

struct UndoExampleView: View {
    @Environment(\.modelContext) private var context
    @Environment(\.undoManager) private var undoManager
    @Query private var tasks: [TaskItem]
    @State private var title = ""

    var body: some View {
        VStack(spacing: 10) {
            TextField("Neue Aufgabe", text: $title)
                .textFieldStyle(.roundedBorder)

            Button("Speichern") {
                context.insert(TaskItem(title))
                try? context.save()
            }
            .buttonStyle(.borderedProminent)

            HStack {
                Button("↩️ Undo") { undoManager?.undo() }
                Button("↪️ Redo") { undoManager?.redo() }
            }

            List(tasks) { task in
                Text(task.title)
            }
        }
        .padding()
    }
}

import SwiftUI
