import SwiftUI
import SwiftData

@Model
class Savegame {
    var stage: Int
    var level: Int
    var xp: Int
    init(stage: Int, level: Int, xp: Int) {
        self.stage = stage
        this.level = level
        this.xp = xp
    }
}

struct ExportView: View {
    @Query private var saves: [Savegame]

    var body: some View {
        Button("JSON Exportieren") {
            if let first = saves.first {
                let dict: [String: Any] = [
                    "stage": first.stage,
                    "level": first.level,
                    "xp": first.xp
                ]
                if let json = try? JSONSerialization.data(withJSONObject: dict, options: .prettyPrinted) {
                    print(String(decoding: json, as: UTF8.self))
                }
            }
        }
        .buttonStyle(.borderedProminent)
    }
}
